import { unstable_cache } from 'next/cache';

export type Post = {
  id: number;
  title: string;
  createdAt: string;
};

const postsTable: Post[] = [
  {
    id: 1,
    title: 'Welcome post',
    createdAt: new Date('2026-02-01T08:00:00.000Z').toISOString()
  }
];

let nextId = 2;

async function readPostsFromStore(): Promise<Post[]> {
  return postsTable.map((post) => ({ ...post }));
}

export const getPosts = unstable_cache(readPostsFromStore, ['posts-list'], {
  tags: ['posts']
});

export async function createPost(title: string): Promise<Post> {
  const post: Post = {
    id: nextId++,
    title,
    createdAt: new Date().toISOString()
  };

  postsTable.unshift(post);
  return { ...post };
}

